"""stages.implement.delivery: generated by the graph.py split (P1)."""

from __future__ import annotations

from typing import Any

from ...runtime import coding_session, coding_tools, conformance_delivery, observations, stage_services, tools
from ...runtime.policy import PolicyError
from ...runtime.tools import RepoToolbox
from ...stages import feedback
from ...state import CfuDesignState


class DeliveryTransaction:
    """Entry-byte snapshot of the bounded no-tool implementation surface."""

    def __init__(self, state: CfuDesignState, toolbox: RepoToolbox):
        from . import intrinsics

        self.toolbox = toolbox
        paths = set(tools.design_workspace_paths(state.get("run_root", "")).values())
        paths.update(path for path, _ in stage_services._software_targets(state, toolbox))
        header = intrinsics.intrinsics_header_path(state)
        if header:
            paths.add(header)
        paths.update(conformance_delivery.delivery_paths(state).values())
        # Never follow state artifact refs, redirect a snapshot, or read before
        # policy/current-run validation. The same fixed paths are used to restore.
        self.snapshot = conformance_delivery._snapshot(
            toolbox, {path: path for path in sorted(paths)}, write=True)

    def rollback(self) -> None:
        conformance_delivery._restore(self.toolbox, self.snapshot)


def repair_route_output(state, text, toolbox):
    """Validate a plain-delivery rewind before applying any source content."""
    value = coding_tools.parse_repair_route(text)
    if value is None:
        return None
    if tools.extract_edit_blocks(text) or tools.extract_file_blocks(text) or tools.extract_patch(text):
        raise ValueError("an upstream REPAIR_ROUTE cannot be mixed with source delivery")
    if set(value) != {"target", "reason", "failure_ids", "diagnosis"}:
        raise ValueError("REPAIR_ROUTE requires target, reason, failure_ids and diagnosis")
    index = observations.failure_index(state)
    session = coding_session.CodingSession(toolbox, frozenset(), failure_index=index, diagnosis_required=True)
    if not isinstance(value["diagnosis"], dict):
        raise ValueError("REPAIR_ROUTE requires a structured diagnosis")
    answer = session.submit_diagnosis(value["diagnosis"])
    if not answer.startswith("diagnosis accepted"):
        raise ValueError(answer)
    route = coding_tools.validate_repair_route(
        {key: value[key] for key in ("target", "reason", "failure_ids")},
        diagnosis=session.diagnosis, failure_index=index,
        repair_mode=bool(feedback.all_failure_feedback(state)))
    if route["target"] == "implement":
        raise ValueError("implement stays in this round: deliver the ordinary diagnosed source repair")
    return {"repair_route": route}


def _validate_targets(state, toolbox, edit_blocks, file_blocks, patch_text, domain):
    """Model source delivery cannot overwrite host-owned oracle/C/header files."""
    # Host-neutral planning tests intentionally have no repository toolbox.
    if not state.get("run_root") and not hasattr(toolbox, "resolve_target"):
        return
    domain = domain or state.get("_implementation_domain", "")
    if domain not in ("", "hardware", "software"):
        raise ValueError(f"unknown implementation delivery domain: {domain}")
    hardware = set(tools.design_workspace_paths(state.get("run_root", "")).values())
    software = {path for path, _ in stage_services._software_targets(state, toolbox)}
    allowed = hardware if domain == "hardware" else software if domain == "software" else hardware | software
    allowed = {toolbox.normalize(path) for path in allowed}
    from . import intrinsics
    host_owned = set(conformance_delivery.delivery_paths(state).values())
    header = intrinsics.intrinsics_header_path(state)
    if header:
        host_owned.add(header)
    allowed.difference_update(toolbox.normalize(path) for path in host_owned)
    targets = [path for path, _ in (edit_blocks or file_blocks)]
    if patch_text:
        targets = tools.validate_text_patch(patch_text)
    for target in targets:
        resolved = toolbox.resolve_target(target)
        if (resolved not in allowed or not toolbox.is_current_run_path(resolved)
                or not toolbox.is_write_allowed(resolved)):
            raise PolicyError(
                f"{domain or 'implementation'} delivery target is outside its source domain: {target}; "
                f"legal targets: {', '.join(sorted(allowed)) or '(none)'}")


def _apply_agent_output(
    state: CfuDesignState,
    text: str,
    *,
    toolbox: RepoToolbox,
    require_diagnosis: bool = False,
    attempts: Any = None,
    domain: str = "",
) -> dict[str, Any]:
    """Apply an LLM response's edits, FILE_BEGIN blocks, or patch.

    Shared by the hardware and software rungs so all three delivery protocols
    honour the same write policy and the same dry-run semantics. Targeted
    SEARCH/REPLACE edits are preferred: they are the cheapest to emit and they
    expose the actual change instead of forcing a full-file rewrite.

    The prompt shows, and the protocol edits, the *live run-workspace* content:
    repairs therefore compose on top of earlier attempts instead of being reset
    against the tracked original (which the prompt does not show).

    ``require_diagnosis`` enforces the repair contract: a repair answer that
    skips the REPAIR_DIAGNOSIS section is rejected before anything is applied,
    so root-cause reasoning can never be silently skipped.
    """
    # A malformed/unauthorized route is a delivery rejection, never a source edit.
    if "REPAIR_ROUTE" in (text or ""):
        return {"patch": "", "summary": text or "", "errors": ["invalid REPAIR_ROUTE delivery"],
                "applied": False, "files": [], "apply_result": None, "gate_ok": False, "proposed": False}
    if require_diagnosis and "REPAIR_DIAGNOSIS" not in (text or ""):
        reason = (
            "the repair response omitted the required REPAIR_DIAGNOSIS section (Observed "
            "errors / Root cause / Repair mapping / Regression risks) before the delivery "
            "block; nothing was applied. Re-send the repair with that section first."
        )
        return {"patch": "", "summary": (text or "") + "\n\nRejected: " + reason,
                "errors": [reason], "applied": False, "files": [], "apply_result": None,
                "gate_ok": False, "proposed": False}
    if attempts is not None:
        repeated = feedback._repeated_delivery_error(attempts, text)
        if repeated:
            return {"patch": tools.extract_patch(text or ""),
                    "summary": (text or "") + "\n\nRejected: " + repeated,
                    "errors": [repeated], "applied": False, "files": [],
                    "apply_result": None, "gate_ok": False, "proposed": False}
    edit_blocks = tools.extract_edit_blocks(text)
    file_blocks = tools.extract_file_blocks(text)
    patch_text = tools.extract_patch(text)
    summary = text
    errors: list[str] = []
    apply_result: dict | None = None
    dry_run = bool(state.get("dry_run", False))
    # ``apply_patch`` is the default-on capability for writing LLM-authored
    # content into the run workspace (``--no-apply-patch`` / ``--dry-run``
    # disable it). Without it, every delivery protocol stays a proposal even
    # when external commands are allowed to run.
    apply_patch = bool(state.get("apply_patch", False))
    allow_apply = apply_patch and not dry_run
    protocol_count = sum(bool(value) for value in (edit_blocks, file_blocks, patch_text))
    if protocol_count > 1 or tools.unterminated_edit_blocks(text):
        reason = "mixed delivery protocols" if protocol_count > 1 else "the response opened an EDIT_BEGIN section but the block was not closed (missing EDIT_END)"
        return {"patch": patch_text, "summary": text + "\n\nRejected: " + reason,
                "errors": [reason], "applied": False, "files": [], "apply_result": None,
                "gate_ok": False, "proposed": False}

    try:
        if edit_blocks or file_blocks or patch_text:
            _validate_targets(state, toolbox, edit_blocks, file_blocks, patch_text, domain)
    except (PolicyError, ValueError) as exc:
        reason = f"delivery targets rejected: {exc}"
        return {"patch": patch_text, "summary": text + "\n\nRejected: " + reason,
                "errors": [reason], "applied": False, "files": [], "apply_result": None,
                "gate_ok": False, "proposed": False}

    if edit_blocks and allow_apply:
        try:
            apply_result = toolbox.apply_edit_blocks(edit_blocks)
            summary += "\n\nEdit result:\n" + str(apply_result)
            if apply_result.get("returncode") not in (0, None):
                # Keep the localized mismatch report intact: it names the exact
                # line the model mis-copied, which is what breaks the retry loop.
                reason = str(apply_result.get("stderr_tail", "")).strip()[:1500]
                errors.append(f"targeted edits did not apply: {reason}")
        except (PolicyError, ValueError) as exc:
            errors.append(f"targeted edits failed: {exc}")
    elif file_blocks and allow_apply:
        try:
            apply_result = toolbox.apply_file_blocks(file_blocks)
            summary += "\n\nFile result:\n" + str(apply_result)
            if apply_result.get("returncode") != 0:
                errors.append(f"file blocks rejected: {apply_result.get('stderr_tail', '')}")
        except (PolicyError, ValueError) as exc:
            errors.append(f"file blocks rejected: {exc}")
    elif patch_text and allow_apply:
        try:
            apply_result = toolbox.apply_patch_text(patch_text)
            summary += "\n\nPatch result:\n" + str(apply_result)
            if apply_result.get("returncode") not in (0, None):
                errors.append(f"patch did not apply: {apply_result.get('stderr_tail', '').strip()[:400]}")
        except (PolicyError, ValueError) as exc:
            errors.append(f"patch failed: {exc}")
    elif not dry_run:
        if not apply_patch and (edit_blocks or file_blocks or patch_text):
            summary += (
                "\n\nPatch application is disabled (--no-apply-patch or --dry-run); "
                "this rung remains a design proposal and was not applied."
            )
            errors.append(
                "patch application is disabled: drop --no-apply-patch/--dry-run to let the "
                "agent modify the run workspace"
            )
        else:
            note = (
                "the answer contained no EDIT_BEGIN/FILE_BEGIN/PATCH_BEGIN "
                "deliverable; nothing was applied"
            )
            if tools.unterminated_edit_blocks(text):
                note += (
                    " (the response opened an EDIT_BEGIN section but the block was not "
                    "closed: the terminator must be a line equal to EDIT_END)"
                )
            summary += f"\n\n{note}."
            errors.append(note)

    applied = bool(apply_result) and apply_result.get("returncode") == 0 and not apply_result.get("skipped")
    files: list[str] = []
    if applied:
        parsed = (apply_result or {}).get("parsed", {}) or {}
        files = list(parsed.get("touched_paths", []) or []) or list(parsed.get("redirected_paths", []) or [])
    proposed = bool(edit_blocks or file_blocks or patch_text)
    gate_ok = proposed if dry_run else applied
    return {
        "patch": patch_text,
        "summary": summary,
        "errors": errors,
        "applied": applied,
        "files": files,
        "apply_result": apply_result,
        "gate_ok": gate_ok,
        "proposed": proposed,
    }
